+    void updateAutoLock()
+    {
+        if (data && data->status == VaultInfo::Opened && data->autoLockTimeout > 0) {
+            if (!autoLockTimer.isActive()) {
+                unusedTimer.start();
+                autoLockTimer.start();
+            }
+        } else {
+            autoLockTimer.stop();
+        }
     }

+    void checkAutoLock()
+    {
+        if (q->isBusy()) {
+            return;
+        }
+
+        if (isInUse()) {
+            unusedTimer.start();
+
+        } else if (unusedTimer.hasExpired(data->autoLockTimeout * 60 * 1000LL)) {
+            unusedTimer.start();
+            q->close();
+        }
+    }
+
+    // The vault is in use while one of the user's processes has a file,
+    // its working directory or a mapping inside it, or watches something
+    // in it (file managers watch the folders they show)
+    bool isInUse() const
+    {
+        const QString mountPointPath = QDir(data->mountPoint.data()).canonicalPath();
+
+        struct stat mountPointStat;
+        if (mountPointPath.isEmpty() || ::stat(QFile::encodeName(mountPointPath).constData(), &mountPointStat) != 0) {
+            return true;
+        }
+
+        const auto device = mountPointStat.st_dev;
+        const QByteArray mapsDevice =
+            QByteArray::number(major(device), 16).rightJustified(2, '0') + ':' + QByteArray::number(minor(device), 16).rightJustified(2, '0');
+        const QByteArray inotifyDevice = "sdev:" + QByteArray::number((quint64(major(device)) << 20) | minor(device), 16) + ' ';
+
+        const auto isInVault = [&mountPointPath](const QString &path) {
+            return path == mountPointPath || path.startsWith(mountPointPath + QLatin1Char('/'));
+        };
+
+        const auto linkTarget = [](const QString &link) {
+            char buffer[PATH_MAX];
+            const auto length = ::readlink(QFile::encodeName(link).constData(), buffer, sizeof(buffer));
+            return length > 0 ? QFile::decodeName(QByteArray(buffer, length)) : QString();
+        };
+
+        const auto readFile = [](const QString &path) {
+            QFile file(path);
+            return file.open(QIODevice::ReadOnly) ? file.readAll() : QByteArray();
+        };
+
+        const auto pids = QDir(QStringLiteral("/proc")).entryList(QDir::Dirs | QDir::NoDotAndDotDot);
+        for (const auto &pid : pids) {
+            if (pid.toInt() <= 0) {
+                continue;
+            }
+
+            const QString processDir = QStringLiteral("/proc/") + pid;
+
+            if (isInVault(linkTarget(processDir + QStringLiteral("/cwd"))) || isInVault(linkTarget(processDir + QStringLiteral("/root")))) {
+                return true;
+            }
+
+            const auto fds = QDir(processDir + QStringLiteral("/fd")).entryList(QDir::System | QDir::NoDotAndDotDot);
+            for (const auto &fd : fds) {
+                const auto target = linkTarget(processDir + QStringLiteral("/fd/") + fd);
+
+                if (isInVault(target)) {
+                    return true;
+                }

+                if (target == QLatin1String("anon_inode:inotify") && readFile(processDir + QStringLiteral("/fdinfo/") + fd).contains(inotifyDevice)) {
+                    return true;
+                }
+            }
+
+            const auto maps = readFile(processDir + QStringLiteral("/maps")).split('\n');
+            for (const auto &map : maps) {
+                // address perms offset dev inode path
+                if (map.split(' ').value(3) == mapsDevice) {
+                    return true;
+                }
+            }
+        }
+
+        return false;
+    }

